const raw = $json.body ?? $json;
const firstEntry = Array.isArray(raw.entry) ? raw.entry[0] : undefined;
const firstChange = Array.isArray(firstEntry?.changes) ? firstEntry.changes[0]?.value : undefined;
const data = raw.data ?? raw.lead ?? raw;
const change = firstChange ?? {};
const fieldData = raw.field_data ?? data.field_data ?? change.field_data ?? [];

const leadgenId = raw.leadgen_id ?? data.leadgen_id ?? change.leadgen_id ?? raw.id ?? data.id;
const formId = raw.form_id ?? data.form_id ?? change.form_id;
const pageId = raw.page_id ?? data.page_id ?? change.page_id;
const campaignId = raw.campaign_id ?? data.campaign_id ?? change.campaign_id;
const adsetId = raw.adset_id ?? data.adset_id ?? data.adgroup_id ?? change.adset_id ?? change.adgroup_id;
const adId = raw.ad_id ?? data.ad_id ?? change.ad_id;

const haystack = JSON.stringify({ raw, data, change, fieldData, campaignId, adsetId, adId, formId }).toLowerCase();
const isMondrianMarco = haystack.includes('mondrian')
  || campaignId === '120246723565640137'
  || adsetId === '120246723565650137'
  || adId === '120246723565630137';

const payload = {
  ...raw,
  ...data,
  leadgen_id: leadgenId,
  form_id: formId,
  page_id: pageId,
  campaign_id: campaignId,
  adset_id: adsetId,
  ad_id: adId,
  campaign_name: isMondrianMarco
    ? 'Duke Mondrian - Marco - Lead Ads'
    : (raw.campaign_name ?? data.campaign_name ?? change.campaign_name ?? 'Duke desarrollos desde USD 97,000'),
  project: isMondrianMarco ? 'Mondrian' : (raw.project ?? data.project ?? change.project),
  desarrollo: isMondrianMarco ? 'Mondrian' : (raw.desarrollo ?? data.desarrollo ?? change.desarrollo),
  tag: isMondrianMarco ? 'Mondrian' : (raw.tag ?? data.tag ?? change.tag ?? 'meta_ads'),
  source: raw.source ?? 'meta_ads',
  field_data: fieldData
};

return [{
  json: {
    payload,
    p_pool_key: isMondrianMarco ? 'duke_ads_marco' : 'duke_ads_round_robin'
  }
}];
